from typing import List

class Solution:
    def minOperations(self, nums: List[int], x: int, k: int) -> int:
        n = len(nums)

        # Coordinate compression
        vals = sorted(set(nums))
        rank = {v: i + 1 for i, v in enumerate(vals)}
        m = len(vals)

        cnt = [0] * (m + 2)
        sm = [0] * (m + 2)

        # Largest power of 2 <= m
        LOG = 1
        while LOG * 2 <= m:
            LOG *= 2

        costs = []
        total_sum = 0
        mid_pos = (x + 1) // 2  # 1-indexed median position

        for i in range(n):
            val = nums[i]
            r = rank[val]

            # Inline update(r, val, 1)
            idx = r
            while idx <= m:
                cnt[idx] += 1
                sm[idx] += val
                idx += idx & -idx

            total_sum += val

            if i >= x:
                old_val = nums[i - x]
                ro = rank[old_val]

                # Inline update(ro, old_val, -1)
                idx = ro
                while idx <= m:
                    cnt[idx] -= 1
                    sm[idx] -= old_val
                    idx += idx & -idx

                total_sum -= old_val

            if i >= x - 1:
                # Inline find_kth(mid_pos)
                idx_kth = 0
                bit = LOG
                remaining = mid_pos
                while bit > 0:
                    if idx_kth + bit <= m and cnt[idx_kth + bit] < remaining:
                        idx_kth += bit
                        remaining -= cnt[idx_kth]
                    bit //= 2
                mr = idx_kth + 1

                median = vals[mr - 1]

                # Inline query_sm(mr - 1)
                lower_sum = 0
                idx = mr - 1
                while idx > 0:
                    lower_sum += sm[idx]
                    idx -= idx & -idx

                # Inline query_cnt(mr - 1)
                lower_cnt = 0
                idx = mr - 1
                while idx > 0:
                    lower_cnt += cnt[idx]
                    idx -= idx & -idx

                cost = (median * lower_cnt - lower_sum
                        + (total_sum - lower_sum) - median * (x - lower_cnt))
                costs.append(cost)

        # Optimized 1D DP bounded properly
        dp = [0] * (n + 1)
        for j in range(1, k + 1):
            new_dp = [float('inf')] * (n + 1)
            for p in range(j * x, n + 1):
                cand = dp[p - x] + costs[p - x]
                best = new_dp[p - 1]
                if cand < best:
                    best = cand
                new_dp[p] = best
            dp = new_dp

        return dp[n]
